def read_settings(text):
    settings = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Malformed line: {line}")
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if key in settings:
            raise ValueError(f"Duplicate key: {key}")
        if key == 'enabled':
            if value.lower() not in ('true', 'false'):
                raise ValueError(f"Invalid value for 'enabled': {value}")
            settings[key] = value.lower() == 'true'
        else:
            settings[key] = value

    if 'endpoint' not in settings or 'enabled' not in settings:
        raise ValueError("Missing required keys: endpoint or enabled")

    return settings
